{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "Hydroxysafflor yellow A, a large polyglycosylated flavonoid, reached 1026 ng/g in rat brain after systemic dosing, directly demonstrating that polar glycosides can achieve meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "A triterpenoid glycoside (BA10) showed high brain uptake and reversible tracer kinetics in pigs, supporting CNS access for complex glycosides.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "A glucose-bearing compound (2b) reached 3.1 nmol/g in rat brain via GLUT1-mediated transport; the query's glucose moiety provides a plausible transporter-mediated route across the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "The saponin glycoside A-VI penetrated the BBB in healthy rats with a brain concentration of 248.7 ng/g, showing that even large multi-sugar glycosides can enter the brain.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "The glucoside DP had a brain/plasma ratio of 0.8 in mice, indicating ready brain entry for a glucose-containing small molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "PSI-6130 was detected in rhesus monkey CSF after systemic administration despite low oral bioavailability, supporting CNS penetration for sugar-containing nucleosides.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "FLT is reported to have limited BBB permeability in one PET context, providing a contradictory signal, but this is less transferable because it involves a nucleoside and disrupted-BBB/intranasal conditions rather than systemic glycoside exposure.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted pass: multiple glycoside and glucose-containing analogues show direct brain uptake, brain concentrations, or CSF penetration, including transporter-mediated glucose uptake, supporting meaningful CNS access for this glucose-bearing complex glycoside.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the exact query molecule.",
    "Reported brain concentrations are mostly total tissue levels rather than unbound brain concentrations.",
    "Potential efflux-transporter liability of the exact query aglycone is not directly characterized.",
    "Some supportive evidence comes from disease models with disrupted BBB, though healthy-animal data also exist."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

